mapper.select:
select channel_id
from bonus_pool_now
where end_time <= #{time}

mapper.update:
update bonus_pool_now
set order_bonus = order_bonus + #{amount}
where channel_id = #{channelId}

update bonus_pool_now
set custom_bonus = #{amount}
where channel_id = #{channelId}

mapper.delete:
delete from bonus_pool_now
where id = #{bonusPoolId}
and channel_id = #{channelId}
